"use client";

import {brazilToday} from "@/lib/dates";
import React, {useEffect, useMemo, useState} from "react";
import {ArrowDown, ArrowDownLeft, ArrowRight, ArrowUpRight, Banknote, BarChart3, CalendarDays, Check, ChevronDown, ChevronRight, CircleHelp, Coffee, Download, Edit3, ExternalLink, FileSpreadsheet, FileText, Flower2, Headphones, Leaf, LockKeyhole, MapPin, MessageSquare, Plus, Search, ShieldCheck, SlidersHorizontal, Sparkles, Sprout, TrendingUp, Trash2, Trees, Wallet, Wheat, X} from "lucide-react";
import {Area, Bar, BarChart, CartesianGrid, Cell, ComposedChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis} from "recharts";
import "./producer.css";

type Row = Record<string, any>;
type Props = {view:string; data:any; refresh:()=>Promise<void>; notify:(message:string)=>void};
type Field = {key:string; label:string; type?:string; required?:boolean; options?:{value:string;label:string}[]; wide?:boolean; min?:number; step?:string; placeholder?:string};
const brl = (n:number) => new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL",maximumFractionDigits:2}).format(Number(n)||0);
const num = (n:number, maximumFractionDigits=0) => new Intl.NumberFormat("pt-BR",{maximumFractionDigits}).format(Number(n)||0);
const dateLabel = (s:string) => s ? new Date(s.slice(0,10)+"T12:00:00").toLocaleDateString("pt-BR") : "—";
const today = () => brazilToday();
const total = (rows:Row[], key:string) => rows.reduce((n,r)=>n+(Number(r[key])||0),0);
const categories = ["Adubação","Defensivos","Mão de obra","Combustível","Máquinas","Irrigação","Colheita","Transporte","Manutenção","Outras despesas"];
const chartColors = ["#163D2B","#78925D","#B7C7A3","#D9CDB4","#A6B8A1","#DFE6D6","#93A887","#C0B69E","#9C906D","#E8E1D0"];
const monthNames = ["Jan","Fev","Mar","Abr","Mai","Jun","Jul","Ago","Set","Out","Nov","Dez"];
const sampleData = {
 farms:[{id:"example-farm",name:"Fazenda Boa Vista",city:"Patrocínio",state:"MG",totalArea:86,cultivatedArea:64,plants:224000,variety:"Catuaí amarelo",spacing:"3,5 × 0,8 m",year:2016},{id:"example-farm-2",name:"Sítio Bela Terra",city:"Carmo do Paranaíba",state:"MG",totalArea:32,cultivatedArea:24,plants:84000,variety:"Mundo Novo",spacing:"3,5 × 0,8 m",year:2019}],
 plots:[],seasons:[{id:"example-season",name:"Safra 2025 / 2026",year:2026,status:"Em andamento"}],
 productions:[{id:"ep1",farmId:"example-farm",seasonId:"example-season",bags:780,area:19,date:"2026-05-15"},{id:"ep2",farmId:"example-farm",seasonId:"example-season",bags:1120,area:25,date:"2026-06-15"},{id:"ep3",farmId:"example-farm",seasonId:"example-season",bags:980,area:20,date:"2026-07-15"},{id:"ep4",farmId:"example-farm-2",seasonId:"example-season",bags:1000,area:24,date:"2026-08-15"}],
 expenses:[{id:"ee1",farmId:"example-farm",seasonId:"example-season",category:"Adubação",description:"Adubação de cobertura",amount:612500,date:"2026-02-15",status:"Pago"},{id:"ee2",farmId:"example-farm",seasonId:"example-season",category:"Mão de obra",description:"Equipe de campo",amount:478000,date:"2026-04-15",status:"Pago"},{id:"ee3",farmId:"example-farm",seasonId:"example-season",category:"Colheita",description:"Colheita mecanizada",amount:864000,date:"2026-06-15",status:"Pago"},{id:"ee4",farmId:"example-farm-2",seasonId:"example-season",category:"Defensivos",description:"Controle fitossanitário",amount:232000,date:"2026-03-15",status:"Pago"},{id:"ee5",farmId:"example-farm-2",seasonId:"example-season",category:"Outras despesas",description:"Demais operações",amount:119500,date:"2026-07-15",status:"Pago"}],
 revenues:[{id:"er1",farmId:"example-farm",seasonId:"example-season",description:"Venda de café beneficiado",amount:2620000,date:"2026-07-20"},{id:"er2",farmId:"example-farm-2",seasonId:"example-season",description:"Venda de café beneficiado",amount:1311200,date:"2026-08-20"}]
};

export default function Producer({view,data,refresh,notify}:Props) {
 const [farm,setFarm] = useState(""); const [season,setSeason] = useState("");
 const [demo,setDemo] = useState(false); const [modal,setModal] = useState<{entity:string;row?:Row}|null>(null);
 const [form,setForm] = useState<Row>({}); const [busy,setBusy] = useState(false); const [error,setError] = useState("");
 const [query,setQuery] = useState(""); const [category,setCategory] = useState(""); const [plot,setPlot] = useState("");
 const [dateFrom,setDateFrom] = useState(""); const [dateTo,setDateTo] = useState(""); const [showFilters,setShowFilters] = useState(false);
 const [financeTab,setFinanceTab] = useState("expenses"); const [farmDetail,setFarmDetail] = useState("");
 const [reportType,setReportType] = useState("financeiro"); const [sim,setSim] = useState({bags:1000,price:1500,cost:650000});
 const [ticketOpen,setTicketOpen] = useState("");
 const [featureAccess,setFeatureAccess] = useState<Record<string,boolean|null>>({});
 const [billing,setBilling] = useState<{configured:boolean;provider?:string;mode?:string}|null>(null);
 const [billingBusy,setBillingBusy] = useState("");
 useEffect(()=>{if(view!=="assinatura")return;let cancelled=false;fetch("/api/billing").then(async response=>{if(!response.ok)return;const config=await response.json() as {configured:boolean;provider?:string;mode?:string};if(!cancelled)setBilling(config);}).catch(()=>{if(!cancelled)setBilling({configured:false});});return()=>{cancelled=true;};},[view]);
 useEffect(()=>{const key=view==="simulador"?"simulator":view==="relatorios"?"reports":null;if(!key)return;let cancelled=false;fetch(`/api/data?feature=${key}`).then(async response=>{if(!cancelled)setFeatureAccess(previous=>({...previous,[key]:response.ok}));}).catch(()=>{if(!cancelled)setFeatureAccess(previous=>({...previous,[key]:false}));});return()=>{cancelled=true;};},[view,data.profile?.plan]);
 useEffect(()=>{if(!modal)return;const previous=document.body.style.overflow;document.body.style.overflow="hidden";const handleEscape=(event:KeyboardEvent)=>{if(event.key==="Escape"&&!busy)setModal(null);};document.addEventListener("keydown",handleEscape);return()=>{document.body.style.overflow=previous;document.removeEventListener("keydown",handleEscape);};},[modal,busy]);
 const d = demo && view==="dashboard" ? {...data,...sampleData} : data;
 const farms:Row[] = d.farms||[], seasons:Row[] = d.seasons||[], plots:Row[] = d.plots||[];
 const ownPlan = (data.plans||[]).find((p:Row)=>p.id===data.profile?.plan || p.name?.toLowerCase()===String(data.profile?.plan||"").toLowerCase()) || (data.plans||[]).find((p:Row)=>Number(p.price)===0);
 const can = (feature:string) => Boolean(ownPlan?.features?.[feature] && featureAccess[feature]!==false && (Number(ownPlan?.price)===0 || (data.subscription?.verifiedAt && ["active","trialing"].includes(data.subscription.status) && Date.parse(data.subscription.currentPeriodEnd)>Date.now())));
 const filtered = (rows:Row[]) => rows.filter(r=>(!farm||r.farmId===farm)&&(!season||r.seasonId===season));
 const expenses = filtered(d.expenses||[]), production=filtered(d.productions||[]), revenues=filtered(d.revenues||[]);
 const selectedFarms = farms.filter(r=>!farm||r.id===farm);
 const costs=total(expenses,"amount"), income=total(revenues,"amount"), bags=total(production,"bags"), result=income-costs, area=total(selectedFarms,"cultivatedArea");
 const farmName = (id:string) => farms.find(r=>r.id===id)?.name||"Fazenda não encontrada";
 const seasonName = (id:string) => seasons.find(r=>r.id===id)?.name||"Sem safra";
 const plotName = (id:string) => plots.find(r=>r.id===id)?.name||"—";
 const chartYear=Number(seasons.find(r=>r.id===season)?.year)||new Date().getFullYear();
 const monthData = useMemo(()=>monthNames.map((name,i)=>({name,production:production.filter((r:Row)=>new Date(r.date).getMonth()===i&&new Date(r.date).getFullYear()===chartYear).reduce((n:number,r:Row)=>n+Number(r.bags||0),0),costs:expenses.filter((r:Row)=>new Date(r.date).getMonth()===i&&new Date(r.date).getFullYear()===chartYear).reduce((n:number,r:Row)=>n+Number(r.amount||0),0)})),[production,expenses,chartYear]);
 const costData = categories.map((name,i)=>({name,value:total(expenses.filter((r:Row)=>r.category===name),"amount"),color:chartColors[i]})).filter(r=>r.value>0);
 const open = (entity:string,row?:Row) => {setError("");setModal({entity,row});if(demo){setDemo(false);setFarm("");setSeason("");notify("Você voltou para seus dados. Este formulário salva registros reais.");}setForm(row?{...row}:{farmId:demo?data.farms?.[0]?.id||"":farm||farms[0]?.id||"",seasonId:demo?data.seasons?.[0]?.id||"":season||seasons[0]?.id||"",date:today(),year:new Date().getFullYear(),status:entity==="seasons"?"Em planejamento":"Pendente",category:"Adubação",priority:"Normal"});};
 const mutate = async(entity:string,action:string,payload?:Row,id?:string) => {
  setBusy(true);setError("");
  const entityMap:Record<string,string>={farms:"farm",plots:"plot",seasons:"season",expenses:"expense",productions:"production",revenues:"revenue",tickets:"ticket"};
  try {const response=await fetch("/api/data",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({entity:entityMap[entity]||entity,action,id,data:payload})});const res=await response.json() as {error?:string};if(!response.ok)throw new Error(res.error||"Não foi possível salvar. Tente novamente.");await refresh();setModal(null);notify(action==="delete"?"Registro excluído.":"Informações salvas com sucesso.");return true;}catch(e:any){setError(e.message);notify(e.message);return false;}finally{setBusy(false);}
 };
 const remove = (entity:string,row:Row) => {const details=entity==="farms"?"Os talhões, despesas, produções e receitas vinculados também serão excluídos. ":"";if(window.confirm(`Excluir ${row.name||row.description||"este registro"}? ${details}Esta ação não pode ser desfeita.`))void mutate(entity,"delete",undefined,row.id);};
 const entityTitle:Record<string,string>={farms:"fazenda",plots:"talhão",seasons:"safra",expenses:"despesa",productions:"produção",revenues:"receita",tickets:"solicitação"};
 const options=(rows:Row[])=>rows.map(r=>({value:String(r.id),label:r.name}));
 const farmFields:Field[]=[{key:"name",label:"Nome da fazenda",required:true,wide:true,placeholder:"Ex.: Fazenda Boa Vista"},{key:"city",label:"Cidade",required:true},{key:"state",label:"Estado (UF)",required:true,options:["AC","AL","AP","AM","BA","CE","DF","ES","GO","MA","MT","MS","MG","PA","PB","PR","PE","PI","RJ","RN","RS","RO","RR","SC","SP","SE","TO"].map(x=>({value:x,label:x}))},{key:"totalArea",label:"Área total (ha)",type:"number",required:true,min:0.01,step:"0.01"},{key:"cultivatedArea",label:"Área cultivada (ha)",type:"number",required:true,min:0,step:"0.01"},{key:"plants",label:"Quantidade de pés de café",type:"number",min:0,step:"1"},{key:"variety",label:"Variedades de café",placeholder:"Ex.: Catuaí, Mundo Novo"},{key:"spacing",label:"Espaçamento",placeholder:"Ex.: 3,5 × 0,8 m"},{key:"year",label:"Ano de implantação",type:"number",min:1900,step:"1"}];
 const baseFarmField:Field={key:"farmId",label:"Fazenda",required:true,options:options(farms)};
 const baseSeasonField:Field={key:"seasonId",label:"Safra",options:[{value:"",label:"Sem safra específica"},...options(seasons)]};
 const basePlotField:Field={key:"plotId",label:"Talhão",options:[{value:"",label:"Toda a fazenda"},...options(plots.filter(r=>r.farmId===(form.farmId||farms[0]?.id)))]};
 const fields:Record<string,Field[]>={farms:farmFields,plots:[baseFarmField,{key:"name",label:"Nome do talhão",required:true},{key:"area",label:"Área (ha)",type:"number",required:true,min:0.01,step:"0.01"},{key:"plants",label:"Quantidade de plantas",type:"number",min:0,step:"1"},{key:"variety",label:"Variedade"},{key:"year",label:"Ano de implantação",type:"number",min:1900,step:"1"}],seasons:[{key:"name",label:"Nome da safra",required:true,wide:true,placeholder:"Ex.: Safra 2026 / 2027"},{key:"year",label:"Ano da colheita",type:"number",required:true,min:1900,step:"1"},{key:"status",label:"Situação",options:["Em planejamento","Em andamento","Concluída"].map(x=>({value:x,label:x}))}],expenses:[{key:"description",label:"Descrição da despesa",required:true,wide:true},baseFarmField,baseSeasonField,basePlotField,{key:"category",label:"Categoria",required:true,options:categories.map(x=>({value:x,label:x}))},{key:"amount",label:"Valor (R$)",type:"number",required:true,min:0.01,step:"0.01"},{key:"date",label:"Data",type:"date",required:true},{key:"status",label:"Situação",options:["Pago","Pendente"].map(x=>({value:x,label:x}))}],productions:[baseFarmField,baseSeasonField,basePlotField,{key:"bags",label:"Sacas beneficiadas de 60 kg",type:"number",required:true,min:0.01,step:"0.01"},{key:"area",label:"Área colhida (ha)",type:"number",required:true,min:0.01,step:"0.01"},{key:"date",label:"Data da colheita",type:"date",required:true}],revenues:[{key:"description",label:"Descrição da receita",required:true,wide:true},baseFarmField,baseSeasonField,{key:"amount",label:"Valor recebido (R$)",type:"number",required:true,min:0.01,step:"0.01"},{key:"date",label:"Data do recebimento",type:"date",required:true}],tickets:[{key:"subject",label:"Assunto",required:true,wide:true,placeholder:"Como podemos ajudar?"},{key:"priority",label:"Prioridade",options:["Normal","Alta","Urgente"].map(x=>({value:x,label:x}))},{key:"message",label:"Conte o que aconteceu",type:"textarea",required:true,wide:true,placeholder:"Descreva sua dúvida ou dificuldade…"}]};
 const submit=(e:React.FormEvent) => {e.preventDefault();if(!modal)return;const payload:Row={};for(const field of fields[modal.entity]||[]){const value=form[field.key];if(field.type==="number")payload[field.key]=field.key==="year"?Number(value||new Date().getFullYear()):Number(value||0);else if(value!==undefined)payload[field.key]=value;}if(modal.entity==="farms"&&payload.cultivatedArea>payload.totalArea){setError("A área cultivada deve ser menor ou igual à área total.");return;}if(["productions","expenses","revenues","plots"].includes(modal.entity)&&!payload.farmId){setError("Cadastre uma fazenda antes de adicionar este registro.");return;}void mutate(modal.entity,modal.row?"update":"create",payload,modal.row?.id);};
 const checkExport=async()=>{try{const response=await fetch("/api/data?feature=export");if(!response.ok){const message=await response.json() as {error?:string};throw new Error(message.error||"A exportação não está disponível no seu plano.");}return true;}catch(e:any){notify(e.message);return false;}};
 const exportCSV=async()=>{if(!can("export")){notify("A exportação está disponível nos planos com esse recurso ativo.");return;}if(!await checkExport())return;const rows=reportRows();const keys=Object.keys(rows[0]||{});if(!keys.length){notify("Ainda não há dados para exportar.");return;}const escapeCSV=(value:any)=>'"'+String(value??"").replace(/^[=+\-@\t\r]/,"'$&").replaceAll('"','""')+'"';const csv="\uFEFF"+[keys.map(escapeCSV).join(";"),...rows.map(r=>keys.map(k=>escapeCSV(r[k])).join(";"))].join("\r\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8;"}));const a=document.createElement("a");a.href=url;a.download=`cafegestor-${reportType}-${today()}.csv`;a.click();URL.revokeObjectURL(url);notify("Arquivo CSV exportado. Compatível com Excel.");};
 const reportRows=():Row[]=>{
  if(reportType==="safras")return seasons.filter(s=>!season||s.id===season).map(s=>{
   const p=total((d.productions||[]).filter((x:Row)=>x.seasonId===s.id&&(!farm||x.farmId===farm)),"bags");
   const c=total((d.expenses||[]).filter((x:Row)=>x.seasonId===s.id&&(!farm||x.farmId===farm)),"amount");
   const r=total((d.revenues||[]).filter((x:Row)=>x.seasonId===s.id&&(!farm||x.farmId===farm)),"amount");
   return {Safra:s.name,"Produção (sc)":p,"Custos (R$)":c,"Receita (R$)":r,"Resultado (R$)":r-c};
  });
  if(reportType==="producao")return production.map((r:Row)=>({Fazenda:farmName(r.farmId),Safra:seasonName(r.seasonId),Data:dateLabel(r.date),Sacas:r.bags,"Área (ha)":r.area,"Sacas/ha":Number(r.area)?Number(r.bags)/Number(r.area):0}));
  if(reportType==="custos")return expenses.map((r:Row)=>({Descrição:r.description,Fazenda:farmName(r.farmId),Categoria:r.category,Data:dateLabel(r.date),"Valor (R$)":r.amount,Situação:r.status}));
  if(reportType==="financeiro")return [...expenses.map((r:Row)=>({Tipo:"Despesa",Fazenda:farmName(r.farmId),Descrição:r.description,Data:dateLabel(r.date),"Entrada (R$)":0,"Saída (R$)":Number(r.amount)})),...revenues.map((r:Row)=>({Tipo:"Receita",Fazenda:farmName(r.farmId),Descrição:r.description,Data:dateLabel(r.date),"Entrada (R$)":Number(r.amount),"Saída (R$)":0}))];
  return selectedFarms.map(r=>{
   const e=total(expenses.filter((x:Row)=>x.farmId===r.id),"amount"),re=total(revenues.filter((x:Row)=>x.farmId===r.id),"amount"),b=total(production.filter((x:Row)=>x.farmId===r.id),"bags");
   return {Fazenda:r.name,"Receita (R$)":re,"Custos (R$)":e,"Resultado (R$)":re-e,"Margem (%)":re?(re-e)/re*100:0,"Produção (sc)":b,"Custo/saca (R$)":b?e/b:0};
  });
 };
 const exportExcel=async()=>{
  if(!can("export")){notify("A exportação está disponível nos planos com esse recurso ativo.");return;}
  if(!await checkExport())return;
  const rows=reportRows();if(!rows.length){notify("Ainda não há dados para exportar.");return;}
  try{
   const {downloadXlsx}=await import("@/lib/export-xlsx");
   downloadXlsx(`cafegestor-${reportType}-${today()}.xlsx`,{title:"Relatório CaféGestor",sheets:[{name:"Relatório",title:"CaféGestor · "+reportType,description:(farm?farmName(farm):"Todas as fazendas")+" · "+(season?seasonName(season):"Todas as safras"),columns:Object.keys(rows[0]).map(key=>({key,label:key,width:key==="Descrição"||key==="Fazenda"?30:22,format:key.includes("R$")?"currency" as const:typeof rows[0][key]==="number"?"decimal" as const:"text" as const})),rows}]});
   notify("Relatório Excel exportado com sucesso.");
  }catch{notify("Não foi possível gerar o arquivo Excel. Tente novamente.");}
 };
 const billingAction=async(action:"checkout"|"portal",plan?:Row)=>{
  setBillingBusy(plan?.id||"portal");
  try{const response=await fetch("/api/billing",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({action,...(plan?{planId:plan.id,period:plan.period}:{})})});const result=await response.json() as {url?:string;error?:string};if(!response.ok||!result.url)throw new Error(result.error||"Não foi possível iniciar o atendimento de assinatura.");window.location.assign(result.url);}catch(e:any){notify(e.message);setBillingBusy("");}
 };
 const selectPlan=(plan:Row)=>{if(billing?.configured&&(data.billingSubscription||data.subscription)){void billingAction("portal");return;}if(billing?.configured&&Number(plan.price)>0){void billingAction("checkout",plan);return;}open("tickets");setForm({subject:`Interesse no plano ${plan.name}`,message:`Olá! Gostaria de conhecer as condições para contratar o plano ${plan.name}.`,priority:"Normal"});};
 const financeRows=(financeTab==="expenses"?expenses:revenues).filter((r:Row)=>(!query||[r.description,farmName(r.farmId)].join(" ").toLowerCase().includes(query.toLowerCase()))&&(!plot||r.plotId===plot)&&(!category||financeTab!=="expenses"||r.category===category)&&(!dateFrom||r.date>=dateFrom)&&(!dateTo||r.date.slice(0,10)<=dateTo));
 const filters = <div className="p-filters"><div className="p-select-wrap"><Trees size={15}/><select aria-label="Selecionar fazenda" value={farm} onChange={e=>{setFarm(e.target.value);setPlot("");}}><option value="">Todas as fazendas</option>{farms.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select><ChevronDown size={14}/></div><div className="p-select-wrap"><CalendarDays size={15}/><select aria-label="Selecionar safra" value={season} onChange={e=>setSeason(e.target.value)}><option value="">Todas as safras</option>{seasons.map(r=><option key={r.id} value={r.id}>{r.name}</option>)}</select><ChevronDown size={14}/></div></div>;
 const heading=(eyebrow:string,title:string,description:string,actions?:React.ReactNode)=><div className="p-heading"><div><div className="p-eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="p-heading-actions">{actions}</div></div>;
 const empty=(icon:React.ReactNode,title:string,text:string,action?:React.ReactNode)=><div className="p-empty"><div className="p-empty-icon">{icon}</div><h3>{title}</h3><p>{text}</p>{action}</div>;
 const rowActions=(entity:string,row:Row)=><div className="p-row-actions"><button title="Editar registro" aria-label="Editar registro" onClick={()=>open(entity,row)}><Edit3 size={15}/></button><button title="Excluir registro" aria-label="Excluir registro" onClick={()=>remove(entity,row)}><Trash2 size={15}/></button></div>;
 const lock=(title:string,text:string)=><div className="p-feature-lock"><div className="p-lock-orbit"><LockKeyhole size={29}/><Sparkles className="p-lock-spark" size={20}/></div><span className="p-label">MAIS VISÃO PARA CRESCER</span><h2>{title}</h2><p>{text}</p><a href="/assinatura" className="p-btn p-btn-primary">Conhecer os planos <ArrowRight size={16}/></a><div className="p-lock-points"><span><Check size={14}/> Gestão mais completa</span><span><Check size={14}/> Decisões com clareza</span></div></div>;

 return <div className="producer">
  {view==="dashboard"&&<>
   {heading("VISÃO GERAL","Seu café. Seus resultados.","Tudo o que importa para uma gestão que dá frutos.",<><span className="p-updated"><span/> Dados atualizados</span><button className="p-btn p-btn-primary" onClick={()=>open("expenses")}><Plus size={17}/> Novo lançamento</button></>)}
   <div className="p-overview-top">{filters}<button className={`p-example ${demo?"is-active":""}`} onClick={()=>{setDemo(!demo);setFarm("");setSeason("");}}><Sparkles size={14}/>{demo?"Sair do exemplo":"Explorar exemplo"}<ArrowUpRight size={13}/></button></div>
   {demo&&<div className="p-demo-notice"><Sparkles size={16}/><span>Você está explorando dados ilustrativos. Eles não fazem parte dos seus registros.</span><button onClick={()=>setDemo(false)} aria-label="Fechar exemplo"><X size={16}/></button></div>}
   <div className="p-kpi-grid">
    <Metric icon={<Coffee size={18}/>} label="Produção total" value={num(bags)} suffix="sacas" note="Beneficiadas de 60 kg" tone="green"/>
    <Metric icon={<ArrowDownLeft size={19}/>} label="Receita total" value={brl(income)} note="Recebimentos registrados"/>
    <Metric icon={<Wallet size={18}/>} label="Custo total" value={brl(costs)} note="Despesas da operação"/>
    <Metric icon={<TrendingUp size={19}/>} label="Resultado financeiro" value={brl(result)} note={income?`${num(result/income*100,1)}% de margem sobre a receita`:"Receita menos custos"} dark/>
   </div>
   <div className="p-farm-strip"><div><span className="p-strip-icon"><Trees size={20}/></span><span><small>Fazendas</small><strong>{num(selectedFarms.length)} <span>propriedades</span></strong></span></div><div><span className="p-strip-icon"><Sprout size={20}/></span><span><small>Área cultivada</small><strong>{num(area,1)} <span>hectares</span></strong></span></div><div><span className="p-strip-icon"><Leaf size={20}/></span><span><small>Pés de café</small><strong>{num(total(selectedFarms,"plants"))} <span>plantas</span></strong></span></div><div><span className="p-strip-icon"><BarChart3 size={20}/></span><span><small>Custo médio / saca</small><strong>{brl(bags?costs/bags:0)}</strong></span></div></div>
   <div className="p-charts-grid"><section className="p-card p-main-chart"><div className="p-card-head"><div><h2>O ritmo da sua safra</h2><p>Produção e custos ao longo do ano</p></div><span className="p-chart-year"><CalendarDays size={14}/>{seasons.find(r=>r.id===season)?.year||new Date().getFullYear()}</span></div><div className="p-chart-legend"><span><i style={{background:"#557A46"}}/>Produção (sc)</span><span><i style={{background:"#DACBB3"}}/>Custos (R$)</span></div><div className="p-chart-box"><ResponsiveContainer width="100%" height="100%"><ComposedChart data={monthData} margin={{top:12,right:2,bottom:0,left:-20}}><defs><linearGradient id="productionFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#557A46" stopOpacity={0.2}/><stop offset="95%" stopColor="#557A46" stopOpacity={0.015}/></linearGradient></defs><CartesianGrid vertical={false} stroke="#EEF0EB" strokeDasharray="3 4"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill:"#899087",fontSize:10}} dy={10}/><YAxis yAxisId="production" axisLine={false} tickLine={false} tick={{fill:"#899087",fontSize:10}}/><YAxis yAxisId="costs" orientation="right" hide/><Tooltip contentStyle={{border:"1px solid #E5E9E0",borderRadius:12,fontSize:12,boxShadow:"0 8px 25px #163d2b12"}} formatter={(value:any,name:any)=>[name==="Custos"?brl(Number(value)):num(Number(value))+" sc",name]}/><Bar yAxisId="costs" dataKey="costs" name="Custos" fill="#E4DBC9" radius={[4,4,0,0]} maxBarSize={19}/><Area yAxisId="production" type="monotone" dataKey="production" name="Produção" stroke="#557A46" strokeWidth={2.5} fill="url(#productionFill)" activeDot={{r:5,stroke:"#fff",strokeWidth:3}}/></ComposedChart></ResponsiveContainer></div>{!bags&&!costs&&<div className="p-chart-empty-note">Sua evolução começa no primeiro lançamento.</div>}</section>
   <section className="p-card p-cost-chart"><div className="p-card-head"><div><h2>Para onde vai o investimento</h2><p>Distribuição dos custos por categoria</p></div><a href="/custos" title="Ver custos"><ArrowUpRight size={18}/></a></div><div className="p-donut-box"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={costData.length?costData:[{name:"Sem despesas",value:1}]} innerRadius={65} outerRadius={84} paddingAngle={costData.length?4:0} dataKey="value" stroke="none" startAngle={90} endAngle={-270}>{(costData.length?costData:[{color:"#EDF0E8"}]).map((r,i)=><Cell key={i} fill={r.color}/>)}</Pie>{costData.length>0&&<Tooltip formatter={(value:any)=>brl(Number(value))} contentStyle={{borderRadius:12,fontSize:12,border:"1px solid #E5E9E0"}}/>}</PieChart></ResponsiveContainer><div className="p-donut-center"><small>Custo total</small><strong>{costs>=1000?`R$ ${num(costs/1000,1)} mil`:brl(costs)}</strong></div></div><div className="p-cost-legend">{costData.length?costData.slice(0,4).map(r=><div key={r.name}><span><i style={{background:r.color}}/>{r.name}</span><b>{num(r.value/costs*100,1)}%</b></div>):<div className="p-muted-line">As categorias aparecem ao lançar suas despesas.</div>}</div></section></div>
   <div className="p-bottom-grid"><section className="p-card p-properties"><div className="p-card-head"><div><h2>Suas raízes, em um só lugar</h2><p>Um olhar sobre as suas propriedades</p></div><a className="p-text-link" href="/fazendas">Ver fazendas <ArrowRight size={14}/></a></div>{selectedFarms.length?<div className="p-property-list">{selectedFarms.slice(0,3).map((r,i)=><a href="/fazendas" className="p-property-row" key={r.id}><div className={`p-farm-thumb p-farm-thumb-${i%3}`}><Trees size={25}/></div><div className="p-property-name"><strong>{r.name}</strong><span><MapPin size={11}/>{r.city}{r.state?`, ${r.state}`:""}</span></div><div className="p-property-area"><strong>{num(r.cultivatedArea,1)} ha</strong><span>área cultivada</span></div><span className="p-soft-badge"><span/>{r.variety||"Café"}</span><ChevronRight size={16}/></a>)}</div>:<div className="p-onboard-row"><span className="p-onboard-icon"><Trees size={30}/></span><div><h3>Vamos começar pela sua fazenda?</h3><p>Cadastre a primeira propriedade e plante uma gestão melhor.</p></div><button className="p-btn p-btn-outline" onClick={()=>open("farms")}><Plus size={15}/> Cadastrar fazenda</button></div>}</section><aside className="p-insight-card"><div className="p-insight-top"><span><Leaf size={15}/> CULTIVE BONS RESULTADOS</span><Sparkles size={20}/></div><h3>Mais clareza hoje.<br/>Uma safra melhor amanhã.</h3><p>Acompanhe cada custo e descubra o que realmente faz sua produção crescer.</p><a href="/simulador">Simular minha rentabilidade <ArrowUpRight size={17}/></a><div className="p-leaf-art"><Leaf/><Leaf/><Leaf/></div></aside></div>
   <div className="p-dashboard-footer"><ShieldCheck size={13}/><span>Seus dados protegidos. Suas decisões mais seguras.</span><span className="p-footer-brand">Feito para quem cultiva o futuro.</span></div>
  </>}

  {view==="fazendas"&&<>
   {heading("SUAS PROPRIEDADES","Onde tudo começa.","Organize suas fazendas e conheça cada pedaço da sua produção.",<button className="p-btn p-btn-primary" onClick={()=>open("farms")}><Plus size={17}/> Nova fazenda</button>)}
   <div className="p-mini-metrics"><Metric icon={<Trees size={18}/>} label="Propriedades cadastradas" value={num(farms.length)}/><Metric icon={<Sprout size={18}/>} label="Área cultivada" value={num(total(farms,"cultivatedArea"),1)} suffix="ha"/><Metric icon={<Leaf size={18}/>} label="Pés de café" value={num(total(farms,"plants"))}/></div>
   <div className="p-toolbar"><div className="p-search"><Search size={16}/><input placeholder="Buscar fazenda ou cidade…" value={query} onChange={e=>setQuery(e.target.value)}/></div><span className="p-count">{farms.length} {farms.length===1?"propriedade":"propriedades"}</span></div>
   {farms.length?<div className="p-farm-grid">{farms.filter(r=>[r.name,r.city,r.state].join(" ").toLowerCase().includes(query.toLowerCase())).map((r,i)=><article className="p-card p-farm-card" key={r.id}><div className={`p-farm-cover p-farm-cover-${i%3}`}><span className="p-cover-badge"><Leaf size={12}/>{r.variety||"Propriedade cafeeira"}</span><div className="p-cover-lines"/><Trees className="p-cover-tree" size={75}/></div><div className="p-farm-body"><div className="p-farm-title"><div><h2>{r.name}</h2><p><MapPin size={13}/>{r.city}{r.state?` · ${r.state}`:""}</p></div>{rowActions("farms",r)}</div><div className="p-farm-numbers"><div><small>Área cultivada</small><strong>{num(r.cultivatedArea,1)} <span>ha</span></strong></div><div><small>Pés de café</small><strong>{num(r.plants)}</strong></div><div><small>Talhões</small><strong>{plots.filter(p=>p.farmId===r.id).length}</strong></div></div><button className="p-farm-detail" onClick={()=>setFarmDetail(farmDetail===r.id?"":r.id)}>{farmDetail===r.id?"Fechar detalhes":"Gerenciar talhões"}<ChevronRight size={15} className={farmDetail===r.id?"p-rotate":""}/></button>{farmDetail===r.id&&<div className="p-plots"><div className="p-plot-info"><span>Área total: <b>{num(r.totalArea,1)} ha</b></span><span>Espaçamento: <b>{r.spacing||"—"}</b></span><span>Implantação: <b>{r.year||"—"}</b></span></div><div className="p-plots-head"><h3>Talhões da propriedade</h3><button className="p-text-link" onClick={()=>{open("plots");setForm({farmId:r.id});}}><Plus size={14}/> Adicionar</button></div>{plots.filter(p=>p.farmId===r.id).length?plots.filter(p=>p.farmId===r.id).map(p=><div className="p-plot-row" key={p.id}><Sprout size={16}/><div><strong>{p.name}</strong><span>{num(p.area,1)} ha · {num(p.plants)} plantas · {p.variety||"Variedade não informada"}</span></div>{rowActions("plots",p)}</div>):<p className="p-inline-empty">Nenhum talhão cadastrado nesta fazenda.</p>}</div>}</div></article>)}</div>:<section className="p-card">{empty(<Trees size={33}/>,"Uma boa gestão começa pela terra.","Adicione sua primeira fazenda para acompanhar áreas, plantas e resultados.",<button className="p-btn p-btn-primary" onClick={()=>open("farms")}><Plus size={16}/> Cadastrar minha fazenda</button>)}</section>}
   <div className="p-info-bar"><CircleHelp size={17}/><span>Divida suas propriedades em talhões para acompanhar a produtividade e os custos de cada área.</span></div>
  </>}

  {view==="custos"&&<>
   {heading("CONTROLE FINANCEIRO","Cada investimento conta.","Acompanhe suas despesas, receitas e o resultado da sua operação.",<button className="p-btn p-btn-primary" onClick={()=>open(financeTab)}><Plus size={17}/> {financeTab==="expenses"?"Nova despesa":"Nova receita"}</button>)}
   <div className="p-mini-metrics"><Metric icon={<Wallet size={18}/>} label="Despesas no período" value={brl(costs)} note={`${expenses.length} lançamentos`}/><Metric icon={<ArrowDownLeft size={18}/>} label="Receitas no período" value={brl(income)} note={`${revenues.length} lançamentos`}/><Metric icon={<TrendingUp size={18}/>} label="Resultado financeiro" value={brl(result)} note="Receitas menos despesas" dark/></div>
   <section className="p-card p-finance-card"><div className="p-table-top"><div className="p-tabs"><button className={financeTab==="expenses"?"active":""} onClick={()=>setFinanceTab("expenses")}>Despesas <span>{expenses.length}</span></button><button className={financeTab==="revenues"?"active":""} onClick={()=>setFinanceTab("revenues")}>Receitas <span>{revenues.length}</span></button></div><div className="p-search"><Search size={15}/><input placeholder="Buscar lançamento…" value={query} onChange={e=>setQuery(e.target.value)}/></div></div><div className="p-table-filters">{filters}<button className={`p-btn p-btn-outline p-small ${showFilters?"is-active":""}`} onClick={()=>setShowFilters(!showFilters)}><SlidersHorizontal size={14}/> Mais filtros</button><span className="p-filter-count">{financeTab==="expenses"?expenses.length:revenues.length} registros</span></div>{showFilters&&<div className="p-advanced-filters"><label>Talhão<select value={plot} onChange={e=>setPlot(e.target.value)}><option value="">Todos os talhões</option>{plots.filter(p=>!farm||p.farmId===farm).map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>{financeTab==="expenses"&&<label>Categoria<select value={category} onChange={e=>setCategory(e.target.value)}><option value="">Todas as categorias</option>{categories.map(x=><option key={x}>{x}</option>)}</select></label>}<label>De<input type="date" value={dateFrom} onChange={e=>setDateFrom(e.target.value)}/></label><label>Até<input type="date" value={dateTo} onChange={e=>setDateTo(e.target.value)}/></label><button className="p-text-link" onClick={()=>{setPlot("");setCategory("");setDateFrom("");setDateTo("");}}>Limpar</button></div>}
   <div className="p-table-scroll"><table className="p-table"><thead><tr><th>Descrição</th><th>Fazenda / safra</th>{financeTab==="expenses"&&<th>Categoria</th>}<th>Data</th><th>Situação</th><th className="p-right">Valor</th><th/></tr></thead><tbody>{financeRows.map((r:Row)=><tr key={r.id}><td><div className="p-description-cell"><span className={`p-transaction-icon ${financeTab==="revenues"?"is-income":""}`}>{financeTab==="revenues"?<ArrowDownLeft size={16}/>:<ArrowUpRight size={16}/>}</span><strong>{r.description}</strong></div></td><td><div className="p-cell-stack"><strong>{farmName(r.farmId)}</strong><small>{seasonName(r.seasonId)}</small></div></td>{financeTab==="expenses"&&<td><span className="p-category-badge">{r.category}</span></td>}<td className="p-nowrap">{dateLabel(r.date)}</td><td><span className={`p-status ${financeTab==="revenues"||["Pago","pago","paid"].includes(r.status)?"p-status-green":"p-status-amber"}`}><span/>{financeTab==="revenues"?"Recebido":r.status}</span></td><td className="p-right"><strong className={financeTab==="revenues"?"p-green-text":""}>{brl(r.amount)}</strong></td><td>{rowActions(financeTab,r)}</td></tr>)}</tbody></table></div>{!financeRows.length&&((financeTab==="expenses"?expenses:revenues).length?empty(<Search size={29}/>,"Nenhum lançamento com estes filtros.","Ajuste sua busca para encontrar outros registros.",<button className="p-btn p-btn-outline" onClick={()=>{setQuery("");setCategory("");setPlot("");setDateFrom("");setDateTo("");}}>Limpar filtros</button>):empty(<Wallet size={31}/>,financeTab==="expenses"?"Seus custos, sob controle.":"Registre o retorno da sua safra.",financeTab==="expenses"?"Lance a primeira despesa e descubra o custo real da sua produção.":"Adicione os recebimentos das suas vendas para calcular o resultado.",<button className="p-btn p-btn-primary" onClick={()=>open(financeTab)}><Plus size={15}/> {financeTab==="expenses"?"Adicionar despesa":"Adicionar receita"}</button>))}<div className="p-table-footer"><span>Valores em reais (R$)</span><span>Custo médio por saca: <b>{brl(bags?costs/bags:0)}</b></span></div></section>
  </>}

  {view==="safras"&&<>
   {heading("GESTÃO DA PRODUÇÃO","Uma nova safra de possibilidades.","Da primeira colheita ao café beneficiado, acompanhe sua produtividade.",<><button className="p-btn p-btn-outline" onClick={()=>open("seasons")}><Plus size={16}/> Nova safra</button><button className="p-btn p-btn-primary" onClick={()=>open("productions")}><Plus size={17}/> Registrar produção</button></>)}
   <div className="p-overview-top">{filters}</div><div className="p-mini-metrics"><Metric icon={<Coffee size={19}/>} label="Produção total" value={num(bags,1)} suffix="sc" note="Sacas beneficiadas de 60 kg"/><Metric icon={<Sprout size={19}/>} label="Área colhida" value={num(total(production,"area"),1)} suffix="ha"/><Metric icon={<BarChart3 size={19}/>} label="Produtividade média" value={num(total(production,"area")?bags/total(production,"area"):0,1)} suffix="sc/ha" dark/></div>
   <div className="p-seasons-layout"><section className="p-card p-seasons-list"><div className="p-card-head"><div><h2>Suas safras</h2><p>Cada ciclo, uma história de crescimento</p></div><button className="p-icon-button" title="Adicionar safra" onClick={()=>open("seasons")}><Plus size={19}/></button></div>{seasons.length?seasons.map(r=><div className="p-season-row" key={r.id}><span className="p-season-icon"><Wheat size={21}/></span><div><strong>{r.name}</strong><span>{r.year} · {num(total((d.productions||[]).filter((p:Row)=>p.seasonId===r.id),"bags"))} sacas</span></div><span className={`p-status ${r.status==="Concluída"?"p-status-green":r.status==="Em andamento"?"p-status-amber":""}`}>{r.status}</span>{rowActions("seasons",r)}</div>):empty(<CalendarDays size={29}/>,"Prepare o próximo ciclo.","Cadastre uma safra e organize a produção por período.",<button className="p-btn p-btn-outline" onClick={()=>open("seasons")}><Plus size={15}/> Cadastrar safra</button>)}</section><section className="p-card"><div className="p-card-head"><div><h2>Colhendo evolução</h2><p>Produção comparada por safra</p></div><BarChart3 size={18}/></div><div className="p-season-chart"><ResponsiveContainer width="100%" height="100%"><BarChart data={seasons.map(r=>({name:r.name,production:total((d.productions||[]).filter((p:Row)=>p.seasonId===r.id&&(!farm||p.farmId===farm)),"bags")}))} margin={{top:10,left:-20,right:10,bottom:0}}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#EEF0EB"/><XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize:10,fill:"#7E877B"}}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:10,fill:"#7E877B"}}/><Tooltip formatter={(v:any)=>[`${num(Number(v))} sc`,"Produção"]} contentStyle={{borderRadius:12,fontSize:12}}/><Bar dataKey="production" fill="#557A46" radius={[6,6,0,0]} maxBarSize={50}/></BarChart></ResponsiveContainer></div></section></div>
   <section className="p-card"><div className="p-card-head"><div><h2>Registros de produção</h2><p>O resultado do seu trabalho no campo</p></div><span className="p-count">{production.length} registros</span></div><div className="p-table-scroll"><table className="p-table"><thead><tr><th>Fazenda / talhão</th><th>Safra</th><th>Data</th><th className="p-right">Área colhida</th><th className="p-right">Produção</th><th className="p-right">Produtividade</th><th/></tr></thead><tbody>{production.map((r:Row)=><tr key={r.id}><td><div className="p-cell-stack"><strong>{farmName(r.farmId)}</strong><small>{r.plotId?plotName(r.plotId):"Toda a fazenda"}</small></div></td><td>{seasonName(r.seasonId)}</td><td>{dateLabel(r.date)}</td><td className="p-right">{num(r.area,1)} ha</td><td className="p-right"><strong>{num(r.bags,1)} sc</strong></td><td className="p-right"><span className="p-category-badge">{num(Number(r.area)?r.bags/r.area:0,1)} sc/ha</span></td><td>{rowActions("productions",r)}</td></tr>)}</tbody></table></div>{!production.length&&empty(<Coffee size={30}/>,"Cada saca merece ser acompanhada.","Registre a produção para visualizar sua evolução e produtividade.",<button className="p-btn p-btn-primary" onClick={()=>open("productions")}><Plus size={15}/> Registrar produção</button>)}</section>
  </>}

  {view==="simulador"&&<>
   {heading("PLANEJE COM CONFIANÇA","O próximo resultado começa aqui.","Explore cenários e entenda a rentabilidade da sua produção.",<span className="p-pro-badge"><Sparkles size={13}/> RECURSO DO SEU PLANO</span>)}
   {!can("simulator")?lock("Transforme possibilidades em decisões.","Tenha acesso ao simulador de rentabilidade e descubra o impacto do preço, da produção e dos custos nos seus resultados."):<><div className="p-simulator-grid"><section className="p-card p-sim-input"><div className="p-card-head"><div><h2>Desenhe seu cenário</h2><p>Ajuste os valores. Veja o resultado acontecer.</p></div><SlidersHorizontal size={19}/></div><div className="p-sim-fields"><label><span><Coffee size={17}/> Produção estimada</span><div className="p-unit-input"><input type="number" min="0" step="1" value={sim.bags} onChange={e=>setSim({...sim,bags:Math.max(0,Number(e.target.value))})}/><b>sacas de 60 kg</b></div><input className="p-range" type="range" min="0" max="10000" step="1" value={Math.min(10000,sim.bags)} onChange={e=>setSim({...sim,bags:Number(e.target.value)})}/><small>0 sacas <span>10.000 sacas</span></small></label><label><span><Banknote size={17}/> Preço de venda por saca</span><div className="p-unit-input"><b>R$</b><input type="number" min="0" step="0.01" value={sim.price} onChange={e=>setSim({...sim,price:Math.max(0,Number(e.target.value))})}/></div><input className="p-range" type="range" min="0" max="4000" step="0.01" value={Math.min(4000,sim.price)} onChange={e=>setSim({...sim,price:Number(e.target.value)})}/><small>R$ 0 <span>R$ 4.000</span></small></label><label><span><Wallet size={17}/> Custo total da produção</span><div className="p-unit-input"><b>R$</b><input type="number" min="0" step="0.01" value={sim.cost} onChange={e=>setSim({...sim,cost:Math.max(0,Number(e.target.value))})}/></div></label><button className="p-btn p-btn-outline" onClick={()=>setSim({bags,price:bags?Math.round(income/bags*100)/100:0,cost:costs})}><ArrowDown size={15}/> Usar dados dos meus registros</button></div></section><section className="p-sim-results"><div className="p-sim-result-head"><span><TrendingUp size={17}/> SEU CENÁRIO ESTIMADO</span><span className="p-sim-live"><span/> Cálculo automático</span></div><p>Resultado estimado</p><h2 className={sim.bags*sim.price-sim.cost<0?"p-negative":""}>{brl(sim.bags*sim.price-sim.cost)}</h2><div className="p-sim-result-amount"><span>Receita bruta</span><strong>{brl(sim.bags*sim.price)}</strong></div><div className="p-sim-result-amount"><span>Custos de produção</span><strong>{brl(sim.cost)}</strong></div><div className="p-sim-margin"><span>Margem de lucro</span><strong>{num(sim.bags*sim.price?(sim.bags*sim.price-sim.cost)/(sim.bags*sim.price)*100:0,1)}%</strong><div><i style={{width:`${Math.max(0,Math.min(100,sim.bags*sim.price?(sim.bags*sim.price-sim.cost)/(sim.bags*sim.price)*100:0))}%`}}/></div></div><div className="p-sim-two"><div><small>Custo por saca</small><strong>{brl(sim.bags?sim.cost/sim.bags:0)}</strong></div><div><small>Preço de equilíbrio</small><strong>{brl(sim.bags?sim.cost/sim.bags:0)}</strong></div></div><div className="p-sim-note"><Leaf size={20}/><span>{sim.bags===0?"Informe uma produção maior que zero para calcular os valores por saca.":sim.bags*sim.price>=sim.cost?`Acima de ${brl(sim.cost/sim.bags)} por saca, sua produção começa a dar resultado.`:"Neste cenário, a receita ainda não cobre o custo. Explore ajustes no preço, volume ou custo."}</span></div></section></div><div className="p-info-bar"><CircleHelp size={17}/><span>Esta simulação usa apenas os valores informados. É uma projeção e não altera seus registros financeiros.</span></div></>}
  </>}

  {view==="relatorios"&&<>
   {heading("INFORMAÇÃO QUE GERA VALOR","Os números contam a sua história.","Reúna resultados, compare safras e leve sua gestão mais longe.",<><button className="p-btn p-btn-outline" onClick={async()=>{if(can("reports")&&can("export")){if(await checkExport())window.print();}else notify("A exportação exige um plano com o recurso ativo.");}}><FileText size={15}/> Imprimir / PDF</button><button className="p-btn p-btn-primary" onClick={exportExcel}><Download size={16}/> Exportar Excel</button></>)}
   {!can("reports")?lock("Uma visão completa do que você cultiva.","Relatórios de custos, produção e rentabilidade ajudam a entender cada resultado. Acesse um plano com relatórios e tome suas próximas decisões com mais informação."):<><div className="p-report-selector">{[{id:"financeiro",icon:<Banknote size={20}/>,name:"Financeiro",desc:"Receitas, custos e resultado"},{id:"custos",icon:<Wallet size={20}/>,name:"Custos",desc:"Cada investimento em detalhe"},{id:"producao",icon:<Coffee size={20}/>,name:"Produção",desc:"Colheita e produtividade"},{id:"safras",icon:<CalendarDays size={20}/>,name:"Comparação de safras",desc:"A evolução de cada ciclo"},{id:"rentabilidade",icon:<TrendingUp size={20}/>,name:"Rentabilidade",desc:"O resultado de cada fazenda"}].map(r=><button key={r.id} className={reportType===r.id?"active":""} onClick={()=>setReportType(r.id)}>{r.icon}<span><strong>{r.name}</strong><small>{r.desc}</small></span>{reportType===r.id&&<Check size={15}/>}</button>)}</div><div className="p-overview-top">{filters}<span className="p-count">Gerado em {dateLabel(today())}</span></div><section className="p-card p-report"><div className="p-report-title"><span><Leaf size={23}/><b>CaféGestor</b></span><div><h2>Relatório {reportType==="financeiro"?"financeiro":reportType==="custos"?"de custos":reportType==="producao"?"de produção":reportType==="rentabilidade"?"de rentabilidade por fazenda":"comparativo de safras"}</h2><p>{farm?farmName(farm):"Todas as fazendas"} · {season?seasonName(season):"Todas as safras"}</p></div></div><div className="p-report-summary"><div><small>Receita</small><strong>{brl(income)}</strong></div><div><small>Custo</small><strong>{brl(costs)}</strong></div><div><small>Resultado</small><strong>{brl(result)}</strong></div><div><small>Produção</small><strong>{num(bags,1)} sc</strong></div></div><div className="p-table-scroll"><table className="p-table"><thead><tr>{Object.keys(reportRows()[0]||{}).map(x=><th key={x}>{x}</th>)}</tr></thead><tbody>{reportRows().map((r,i)=><tr key={i}>{Object.entries(r).map(([k,v])=><td key={k}>{typeof v==="number"?num(v,2):String(v)}</td>)}</tr>)}</tbody></table></div>{!reportRows().length&&empty(<FileText size={29}/>,"Seu próximo relatório começa com um registro.","Cadastre uma fazenda e adicione dados para visualizar os resultados aqui.")}<div className="p-report-foot"><button className="p-text-link" onClick={exportCSV}><FileSpreadsheet size={12}/> Exportar CSV</button><span>CaféGestor · Dados dos seus registros · {dateLabel(today())}</span></div></section><div className="p-info-bar"><FileSpreadsheet size={17}/><span>Exporte uma planilha Excel com os filtros selecionados. Para PDF, use “Imprimir / PDF” e selecione “Salvar como PDF”.</span></div></>}
  </>}

  {view==="assinatura"&&<>
   {heading("CRESÇA NO SEU RITMO","Um plano para cada etapa.","Escolha as ferramentas certas para o futuro da sua produção.")}
   {billing?.configured&&billing.mode==="test"&&<div className="p-billing-test"><ShieldCheck size={16}/><span>Ambiente de teste Stripe. As transações deste ambiente não geram cobranças reais.</span></div>}
   <section className="p-current-plan"><div><span className="p-current-icon"><ShieldCheck size={27}/></span><div><small>SEU PLANO ATUAL</small><h2>{ownPlan?.name||"Grátis"}</h2><p>{Number(ownPlan?.price||0)===0?"Sua gestão começa aqui, sem mensalidade.":`Situação: ${({active:"ativa",trialing:"em teste",past_due:"pagamento em atraso",canceled:"cancelada",unpaid:"pagamento pendente",incomplete:"aguardando pagamento"} as Record<string,string>)[data.subscription?.status]||"aguardando confirmação"}`}</p></div></div><div><strong>{brl(data.subscription?.amount??ownPlan?.price??0)}<small>/{ownPlan?.period==="annual"?"ano":"mês"}</small></strong><span>{farms.length} de {ownPlan?.farmLimit??1} fazendas em uso</span>{billing?.configured&&(data.billingSubscription||data.subscription)&&<button className="p-btn p-btn-outline p-small" disabled={Boolean(billingBusy)} onClick={()=>billingAction("portal")}>{billingBusy==="portal"?"Abrindo…":"Gerenciar assinatura"}<ExternalLink size={13}/></button>}</div></section>
   <div className="p-plan-grid">{(data.plans||[]).filter((p:Row)=>p.active!==false&&p.visible!==false).sort((a:Row,b:Row)=>(a.order||0)-(b.order||0)).map((p:Row,i:number)=><section className={`p-card p-plan ${i===1?"p-plan-featured":""}`} key={p.id}>{i===1&&<div className="p-plan-topline"><Sparkles size={13}/> MAIS POSSIBILIDADES PARA SUA GESTÃO</div>}<div className="p-plan-inside"><span className="p-plan-symbol">{i===0?<Sprout size={23}/>:i===1?<Trees size={23}/>:<Flower2 size={23}/>}</span><h2>{p.name}</h2><p>{i===0?"O primeiro passo para organizar sua produção.":i===1?"Mais informação para colher melhores resultados.":"Uma gestão completa para voar mais alto."}</p><div className="p-plan-price">{brl(p.price)}<span>/{p.period==="annual"?"ano":"mês"}</span></div><button className={`p-btn ${i===1?"p-btn-primary":"p-btn-outline"}`} disabled={ownPlan?.id===p.id||Boolean(billingBusy)} onClick={()=>selectPlan(p)}>{ownPlan?.id===p.id?<><Check size={15}/> Seu plano atual</>:<>{billingBusy===p.id?"Preparando…":billing?.configured?((data.billingSubscription||data.subscription)?"Alterar plano":"Assinar plano"):"Tenho interesse"} <ArrowRight size={15}/></>}</button><div className="p-plan-divider"/><small>O QUE ESTÁ INCLUÍDO</small><ul><li><Check size={15}/>{`Até ${p.farmLimit} ${p.farmLimit===1?"fazenda":"fazendas"}`}</li><li><Check size={15}/>Até {p.plotLimit} talhões</li>{(p.benefits||[]).filter((b:string)=>!/(fazenda|talh)/i.test(b)).map((b:string,j:number)=><li key={j}><Check size={15}/>{b}</li>)}</ul></div></section>)}</div>
   <div className="p-billing-notice"><span><LockKeyhole size={21}/></span><div><h3>{billing?.configured?"Seu plano, com pagamentos seguros.":"Contratação assistida, com transparência."}</h3><p>{billing?.configured?"A contratação e o gerenciamento da assinatura são realizados no ambiente seguro da Stripe. A liberação dos recursos acontece após a confirmação do pagamento.":"A integração de pagamentos está em preparação. Envie seu interesse pelo plano e nossa equipe orientará os próximos passos. Nenhuma cobrança é realizada nesta página."}</p></div><a href="/suporte">Falar com suporte <ArrowUpRight size={15}/></a></div>
   <section className="p-card p-payment-history"><div className="p-card-head"><div><h2>Histórico de pagamentos</h2><p>Acompanhe os recebimentos confirmados e a situação das cobranças</p></div><FileText size={18}/></div>{(data.payments||[]).length?<div className="p-table-scroll"><table className="p-table"><thead><tr><th>Data</th><th>Referência</th><th>Situação</th><th className="p-right">Valor</th></tr></thead><tbody>{(data.payments||[]).map((payment:Row)=><tr key={payment.id}><td>{dateLabel((payment.paidAt||payment.createdAt||"").slice(0,10))}</td><td>#{String(payment.id).slice(-8).toUpperCase()}</td><td><span className={"p-status "+(["paid","succeeded","pago"].includes(payment.status)?"p-status-green":"p-status-amber")}>{({paid:"Pago",succeeded:"Pago",pending:"Pendente",failed:"Falhou",refunded:"Reembolsado",canceled:"Cancelado"} as Record<string,string>)[payment.status]||payment.status}</span></td><td className="p-right"><strong>{brl(payment.amount)}</strong></td></tr>)}</tbody></table></div>:<div className="p-payment-empty"><ShieldCheck size={21}/><span>Nenhum pagamento registrado até o momento.</span></div>}</section>
  </>}

  {view==="suporte"&&<>
   {heading("PODE CONTAR COM A GENTE","Cuidamos de quem cultiva.","Tire suas dúvidas e acompanhe cada solicitação em um só lugar.",<button className="p-btn p-btn-primary" onClick={()=>open("tickets")}><Plus size={17}/> Nova solicitação</button>)}
   <div className="p-support-intro"><div><span className="p-support-icon"><Headphones size={30}/></span><h2>Uma boa conversa resolve.</h2><p>Conte com a central de suporte para aproveitar melhor o CaféGestor.</p><button className="p-btn p-btn-primary" onClick={()=>open("tickets")}>Como podemos ajudar? <ArrowRight size={16}/></button></div><div className="p-support-art"><MessageSquare size={80}/><span><Leaf size={38}/></span><i/></div></div>
   <section className="p-card"><div className="p-card-head"><div><h2>Suas solicitações</h2><p>Todo o histórico, sempre ao seu alcance</p></div><span className="p-count">{(data.tickets||[]).length} chamados</span></div>{(data.tickets||[]).length?(data.tickets||[]).map((t:Row)=><div className="p-ticket" key={t.id}><button className="p-ticket-top" onClick={()=>setTicketOpen(ticketOpen===t.id?"":t.id)}><span className="p-ticket-icon"><MessageSquare size={20}/></span><span className="p-ticket-name"><strong>{t.subject}</strong><small>#{String(t.id).slice(-6).toUpperCase()} · {t.createdAt?new Date(t.createdAt).toLocaleDateString("pt-BR"):"Solicitação enviada"} · Prioridade {t.priority||"Normal"}</small></span><span className={`p-status ${["Resolvido","Fechado","resolvido","fechado","resolved","closed"].includes(t.status)?"p-status-green":"p-status-amber"}`}>{({aberto:"Aberto",respondido:"Respondido",resolvido:"Resolvido",fechado:"Fechado","em atendimento":"Em atendimento",open:"Aberto",resolved:"Resolvido",closed:"Fechado"} as Record<string,string>)[t.status]||t.status||"Aberto"}</span><ChevronDown size={16}/></button>{ticketOpen===t.id&&<div className="p-ticket-thread"><div className="p-ticket-message"><span>VOCÊ</span><p>{t.message}</p></div>{(t.replies||[]).map((r:Row,i:number)=><div className="p-ticket-message p-ticket-answer" key={i}><span>EQUIPE CAFÉGESTOR {r.date?`· ${dateLabel(r.date)}`:""}</span><p>{r.message||r.text}</p></div>)}{!(t.replies||[]).length&&<p className="p-inline-empty">Sua solicitação está registrada. A resposta aparecerá aqui assim que nossa equipe analisar.</p>}</div>}</div>):empty(<MessageSquare size={30}/>,"Estamos por aqui quando você precisar.","Suas solicitações e as respostas da equipe aparecerão neste espaço.",<button className="p-btn p-btn-outline" onClick={()=>open("tickets")}><Plus size={15}/> Abrir solicitação</button>)}</section>
   <div className="p-help-grid">{[{q:"Por onde começo a usar o CaféGestor?",a:"Cadastre sua fazenda em Fazendas e talhões. Depois, crie uma safra e comece a registrar despesas e produção. Seu painel será atualizado automaticamente."},{q:"Como calculo meu custo por saca?",a:"O CaféGestor divide as despesas registradas pela produção em sacas de 60 kg. Use os filtros de fazenda e safra para ver o custo de cada operação."},{q:"Posso alterar meu plano depois?",a:"Sim. Na página Meu plano, escolha o plano desejado e envie uma solicitação. A equipe orientará as condições e a disponibilidade da contratação."}].map(r=><details key={r.q}><summary>{r.q}<Plus size={16}/></summary><p>{r.a}</p></details>)}</div>
  </>}

  {modal&&<div className="p-modal-backdrop" onClick={e=>{if(e.target===e.currentTarget&&!busy)setModal(null);}}><section className="p-modal" role="dialog" aria-modal="true" aria-labelledby="p-modal-title"><div className="p-modal-head"><div><span className="p-eyebrow">CAFÉGESTOR</span><h2 id="p-modal-title">{modal.row?"Editar":"Adicionar"} {entityTitle[modal.entity]}</h2><p>Informações claras para uma gestão que cresce.</p></div><button className="p-modal-close" onClick={()=>setModal(null)} disabled={busy} aria-label="Fechar formulário"><X size={20}/></button></div><form onSubmit={submit}><div className="p-form-grid">{(fields[modal.entity]||[]).map(f=><label key={f.key} className={f.wide?"p-field-wide":""}>{f.label}{f.required&&<span className="p-required"> *</span>}{f.options?<select value={form[f.key]??""} required={f.required} onChange={e=>setForm({...form,[f.key]:e.target.value,...(f.key==="farmId"?{plotId:""}:{})})}>{!f.options.some(o=>o.value==="")&&<option disabled value="">Selecione…</option>}{f.options.map((o,i)=><option key={`${o.value}-${i}`} value={o.value}>{o.label}</option>)}</select>:f.type==="textarea"?<textarea rows={4} required={f.required} placeholder={f.placeholder} value={form[f.key]??""} onChange={e=>setForm({...form,[f.key]:e.target.value})}/>:<input autoFocus={f===fields[modal.entity][0]} type={f.type||"text"} required={f.required} min={f.min} step={f.step} placeholder={f.placeholder} value={form[f.key]??""} max={f.key==="year"?2100:undefined} maxLength={f.key==="state"?2:undefined} onChange={e=>setForm({...form,[f.key]:e.target.value})}/>}</label>)}</div>{error&&<div className="p-form-error" role="alert">{error}</div>}{["productions","expenses","revenues","plots"].includes(modal.entity)&&!farms.length&&<div className="p-form-error">Cadastre uma fazenda primeiro. <button type="button" onClick={()=>open("farms")}>Cadastrar fazenda</button></div>}<div className="p-modal-footer"><button type="button" className="p-btn p-btn-outline" disabled={busy} onClick={()=>setModal(null)}>Cancelar</button><button className="p-btn p-btn-primary" disabled={busy}>{busy?"Salvando…":modal.entity==="tickets"?"Enviar solicitação":"Salvar informações"}{!busy&&<Check size={16}/>}</button></div></form></section></div>}
 </div>;
}

function Metric({icon,label,value,suffix,note,dark=false,tone=""}:{icon:React.ReactNode;label:string;value:string;suffix?:string;note?:string;dark?:boolean;tone?:string}){return <article className={`p-metric ${dark?"p-metric-dark":""} ${tone?`p-metric-${tone}`:""}`}><div className="p-metric-label"><span>{label}</span><span className="p-metric-icon">{icon}</span></div><div className="p-metric-value">{value}{suffix&&<small>{suffix}</small>}</div>{note&&<div className="p-metric-note">{dark&&<span className="p-metric-dot"/>}{note}</div>}</article>;}


